(()=>{"use strict";const e=document.querySelector("[data-admin-sidebar]");document.querySelector("[data-admin-menu]")?.addEventListener("click",()=>e?.classList.toggle("open")),document.addEventListener("keydown",t=>{"Escape"===t.key&&e?.classList.remove("open")}),document.querySelectorAll("[data-confirm]").forEach(e=>e.addEventListener("submit",t=>{window.confirm(e.dataset.confirm||"هل أنت متأكد؟")||t.preventDefault()}))})();